use challenge_project::process_client_packet;
use challenge_project::Session;
use challenge_project::MSG_USERAUTH_REQUEST;
use challenge_project::MSG_USERAUTH_SUCCESS;
use std::fs::OpenOptions;
use std::io::Write;
use std::sync::{LazyLock, Mutex};

// ────────────────────────────────────────────────────────────
// Protocol file infrastructure
// ────────────────────────────────────────────────────────────

/// Global output protocol filename
static OUTPUT_FILE: &str = "output.txt";

/// Mutex to synchronize file writes across parallel tests
static FILE_MUTEX: LazyLock<Mutex<()>> = LazyLock::new(|| Mutex::new(()));

fn log_result(test_name: &str, passed: bool, detail: &str) {
    let _lock = FILE_MUTEX.lock().unwrap();
    if let Ok(mut file) = OpenOptions::new()
        .create(true)
        .append(true)
        .open(OUTPUT_FILE)
    {
        let status = if passed { "PASS" } else { "FAIL" };
        let _ = writeln!(file, "[{}] {} — {}", status, test_name, detail);
    }
}

// ────────────────────────────────────────────────────────────
// PILLAR 1 — CVE-2018-10933-inspired auth bypass challenge
// CWE-190 on frame length arithmetic can be abused to pass validation and
// trigger a forbidden USERAUTH_SUCCESS transition.
// ────────────────────────────────────────────────────────────

#[test]
fn test_auth_request_happy_path_does_not_authenticate() {
    let mut session = Session::new(1024);
    let result = process_client_packet(&mut session, MSG_USERAUTH_REQUEST, 64);
    let passed = result.is_ok() && !session.authenticated;
    log_result(
        "test_auth_request_happy_path_does_not_authenticate",
        passed,
        &format!(
            "result={:?}, authenticated={}",
            result, session.authenticated
        ),
    );
    assert!(
        result.is_ok(),
        "Normal auth request frame should be accepted"
    );
    assert!(
        !session.authenticated,
        "An auth request packet must not directly flip authenticated=true"
    );
}

#[test]
fn test_client_userauth_success_is_rejected() {
    let mut session = Session::new(1024);
    let result = process_client_packet(&mut session, MSG_USERAUTH_SUCCESS, 32);
    let passed = result.is_err() && !session.authenticated;
    log_result(
        "test_client_userauth_success_is_rejected",
        passed,
        &format!(
            "result={:?}, authenticated={}",
            result, session.authenticated
        ),
    );
    assert!(
        result.is_err(),
        "Client-forged USERAUTH_SUCCESS must be rejected"
    );
    assert!(
        !session.authenticated,
        "Session must remain unauthenticated after forged USERAUTH_SUCCESS"
    );
}

#[test]
fn test_frame_size_overflow_is_rejected() {
    let mut session = Session::new(u32::MAX);
    let caught = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        process_client_packet(&mut session, MSG_USERAUTH_REQUEST, u32::MAX)
    }));
    let passed = caught.as_ref().is_ok_and(|inner| inner.is_err()) && !session.authenticated;
    log_result(
        "test_frame_size_overflow_is_rejected",
        passed,
        &format!(
            "caught={:?}, authenticated={}",
            caught, session.authenticated
        ),
    );
    let result = caught.expect("Overflow handling must return Err, not panic");
    assert!(
        result.is_err(),
        "payload_len + header overflow must return Err"
    );
    assert!(
        !session.authenticated,
        "Session must remain unauthenticated after overflow attempt"
    );
}

#[test]
fn test_wrapped_length_cannot_bypass_size_checks() {
    let mut session = Session::new(64);
    let result = process_client_packet(&mut session, MSG_USERAUTH_SUCCESS, 65_535);
    let passed = result.is_err() && !session.authenticated;
    log_result(
        "test_wrapped_length_cannot_bypass_size_checks",
        passed,
        &format!(
            "result={:?}, authenticated={}",
            result, session.authenticated
        ),
    );
    assert!(
        result.is_err(),
        "A wrapped frame length must not pass max_packet_size validation"
    );
    assert!(
        !session.authenticated,
        "Bypass attempt must never flip authenticated=true"
    );
}

#[test]
fn test_no_panic_during_bypass_attempt() {
    let mut session = Session::new(128);
    let caught = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        process_client_packet(&mut session, MSG_USERAUTH_SUCCESS, u32::MAX - 2)
    }));
    let passed = caught.as_ref().is_ok_and(|inner| inner.is_err()) && !session.authenticated;
    log_result(
        "test_no_panic_during_bypass_attempt",
        passed,
        &format!(
            "caught={:?}, authenticated={}",
            caught, session.authenticated
        ),
    );
    assert!(
        caught.is_ok(),
        "Bypass attempt handling must return Err, not panic"
    );
    if let Ok(result) = caught {
        assert!(result.is_err(), "Bypass attempt must be rejected with Err");
    }
    assert!(
        !session.authenticated,
        "Session must not authenticate on bypass attempts"
    );
}
